const files=[
 {name:'设计素材',type:'文件夹',size:'—',date:'今天 10:24',kind:'folder',icon:'▰'},
 {name:'产品需求说明.md',type:'Markdown',size:'18 KB',date:'今天 09:16',kind:'md',icon:'MD',preview:'markdown'},
 {name:'dashboard-final.png',type:'PNG 图片',size:'2.4 MB',date:'昨天 16:02',kind:'png',icon:'PNG',preview:'image'},
 {name:'项目计划书.pdf',type:'PDF 文档',size:'1.1 MB',date:'10月22日',kind:'pdf',icon:'PDF',preview:'pdf'},
 {name:'todo.txt',type:'纯文本',size:'3 KB',date:'10月20日',kind:'txt',icon:'TXT',preview:'text'},
 {name:'交付包.zip',type:'ZIP 压缩包',size:'8.6 MB',date:'10月18日',kind:'zip',icon:'ZIP',preview:'zip'},
 {name:'会议记录.md',type:'Markdown',size:'6 KB',date:'10月16日',kind:'md',icon:'MD',preview:'markdown'},
 {name:'参考图.png',type:'PNG 图片',size:'860 KB',date:'10月12日',kind:'png',icon:'PNG',preview:'image'}
];let selected=files[1];let currentLayout=0;const layouts=['三栏预览','左右双栏','上下双栏'];const workspace=document.querySelector('.workspace');
function render(filter=''){const list=document.querySelector('#fileList');list.innerHTML='';files.filter(f=>f.name.toLowerCase().includes(filter.toLowerCase())).forEach(f=>{const row=document.createElement('div');row.className='file-row'+(f===selected?' selected':'');row.tabIndex=0;row.innerHTML=`<div class="file-name"><span class="file-icon ${f.kind}-icon">${f.icon}</span><span class="name">${f.name}</span></div><span class="row-date">${f.date}</span><span class="row-type">${f.type}</span><span class="row-size size">${f.size}</span>`;row.onclick=()=>select(f);row.ondblclick=()=>toast(`打开「${f.name}」`);list.append(row)});document.querySelector('#itemCount').textContent=`${files.filter(f=>f.name.toLowerCase().includes(filter.toLowerCase())).length} 个项目 · 按名称排序`;}
function select(f){selected=f;render(document.querySelector('#search').value);document.querySelector('#selectionStatus').textContent=`已选择 1 项`;renderPreview(f);if(innerWidth<=700)document.querySelector('.details').classList.add('open')}
function renderPreview(f){let body='';if(f.preview==='markdown')body=`<div class="preview-box"><h3>项目目标</h3><p>构建简洁、可靠的跨平台文件管理体验。</p><p>支持本地文件浏览、搜索与安全预览。</p><h4>本期范围</h4><p><span class="bullet">•</span> 自适应布局与文件操作</p><p><span class="bullet">•</span> 面向键盘、鼠标与触控输入</p></div>`;else if(f.preview==='image')body=`<div class="preview-box image-preview"><div style="height:120px;border-radius:6px;background:linear-gradient(135deg,#c9d9e9,#e5d5ee 48%,#d7e9dc);display:grid;place-items:center;font-size:28px;color:#76658d">▧</div><p style="text-align:center">图片预览 · 点击打开原图</p></div>`;else if(f.preview==='pdf')body=`<div class="preview-box"><h3>项目计划书</h3><p>PDF 文档预览</p><p>共 12 页 · 1.1 MB</p><p style="margin-top:35px;text-align:center">此原型中显示文件预览占位内容</p></div>`;else body=`<div class="preview-box"><h3>${f.name}</h3><p>${f.type} · ${f.size}</p><p style="margin-top:35px;text-align:center">选择“打开文件”查看完整内容</p></div>`;
 document.querySelector('#previewContent').innerHTML=`<div class="preview-file"><div class="file-name"><span class="file-icon ${f.kind}-icon">${f.icon}</span><span>${f.name}</span></div><p class="subtype">${f.type} · ${f.size}</p></div>${body}<h3 class="info-title">文件信息</h3><div class="info-row"><span>大小</span><span>${f.size}</span></div><div class="info-row"><span>修改时间</span><span>${f.date} · 2026</span></div><div class="info-row"><span>类型</span><span>${f.type}</span></div><div class="info-row"><span>位置</span><span>…/项目资料/${f.name}</span></div><div class="preview-actions"><button class="primary" id="openFile">打开文件</button><button class="text-button" id="moreAction">更多操作　⋯</button></div>`;document.querySelector('#openFile').onclick=()=>toast(`打开「${f.name}」`);document.querySelector('#moreAction').onclick=()=>toast('更多操作：复制路径 · 重命名 · 删除')}
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('show'),2200)}
document.querySelector('#search').addEventListener('input',e=>render(e.target.value));document.querySelector('#newFolder').onclick=()=>{const name=prompt('新文件夹名称','新建文件夹');if(name){files.unshift({name,type:'文件夹',size:'—',date:'刚刚',kind:'folder',icon:'▰'});render(document.querySelector('#search').value);toast(`已创建「${name}」`)}};
document.querySelector('#layoutBtn').onclick=()=>{currentLayout=(currentLayout+1)%3;workspace.classList.remove('split-horizontal','split-vertical');if(currentLayout===1)workspace.classList.add('split-horizontal');if(currentLayout===2)workspace.classList.add('split-vertical');document.querySelector('#layoutBtn').innerHTML=`▥ <span>${layouts[currentLayout]}</span>`;toast(`已切换：${layouts[currentLayout]}`)};
document.querySelector('#splitToggle').onclick=()=>document.querySelector('#layoutBtn').click();document.querySelector('#closeDetails').onclick=()=>document.querySelector('.details').classList.remove('open');document.querySelector('#mobileBack').onclick=()=>toast('返回上一级文件夹');document.querySelector('#mobileSearch').onclick=()=>{const s=document.querySelector('#search');s.focus();s.scrollIntoView({block:'nearest'});toast('请在顶部搜索框输入关键词')};document.querySelector('#mobileMore').onclick=()=>toast('排序 · 新建文件夹 · 选择视图');document.querySelectorAll('.side-item').forEach(b=>b.onclick=()=>{document.querySelectorAll('.side-item').forEach(x=>x.classList.remove('active'));b.classList.add('active');toast(`已切换到：${b.textContent.trim()}`)});document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();document.querySelector('#search').focus()}if(e.key==='Escape')document.querySelector('.details').classList.remove('open')});render();renderPreview(selected);
